import os
import torch
import random
import numpy as np


class Config:
    # =========================================================================
    # Directories and Paths
    # =========================================================================
    INPUT_ROOT = "./input"
    METADATA_DIR = "./metadata"

    # Working directory for caching data and saving models for Idea 3
    WORKING_DIR = "./working/idea_3"

    # Submission directory
    SUBMISSION_DIR = "./submission"

    # Metadata Paths (Generated by previous steps)
    TRAIN_METADATA_PATH = os.path.join(METADATA_DIR, "train.csv")
    VAL_METADATA_PATH = os.path.join(METADATA_DIR, "val.csv")
    TEST_METADATA_PATH = os.path.join(METADATA_DIR, "test.csv")

    # Cache File Paths (npy format)
    # These are used by the data processing module to store/load processed tensors
    CACHE_TRAIN_IMAGES = os.path.join(WORKING_DIR, "train_images.npy")
    CACHE_TRAIN_MASKS = os.path.join(WORKING_DIR, "train_masks.npy")
    CACHE_TRAIN_DEPTHS = os.path.join(WORKING_DIR, "train_depths.npy")

    CACHE_VAL_IMAGES = os.path.join(WORKING_DIR, "val_images.npy")
    CACHE_VAL_MASKS = os.path.join(WORKING_DIR, "val_masks.npy")
    CACHE_VAL_DEPTHS = os.path.join(WORKING_DIR, "val_depths.npy")

    CACHE_TEST_IMAGES = os.path.join(WORKING_DIR, "test_images.npy")
    CACHE_TEST_DEPTHS = os.path.join(WORKING_DIR, "test_depths.npy")

    # Model Output Path
    MODEL_SAVE_PATH = os.path.join(WORKING_DIR, "best_model.pth")

    # Final Submission Path
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # =========================================================================
    # Data Configuration
    # =========================================================================
    IMG_ORIG_SIZE = 101
    IMG_TARGET_SIZE = 128  # Padded size for U-Net like architectures (divisible by 32)
    CHANNELS = 1  # Grayscale input

    # =========================================================================
    # Model Configuration
    # =========================================================================
    ENCODER_NAME = "seresnext50_32x4d"
    ENCODER_WEIGHTS = "imagenet"
    DEPTH_EMBEDDING_DIM = 16  # Dimension for the depth embedding vector

    # =========================================================================
    # Training Hyperparameters
    # =========================================================================
    SEED = 42
    BATCH_SIZE = 32
    EPOCHS = 50
    LEARNING_RATE = 1e-4
    WEIGHT_DECAY = 1e-2
    NUM_WORKERS = 4  # Optimized for 12 vCPUs
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"

    # Early Stopping
    EARLY_STOPPING_PATIENCE = 10
    EARLY_STOPPING_MIN_DELTA = 0.0001

    # =========================================================================
    # Augmentation Parameters
    # =========================================================================
    # Elastic Transform settings
    AUG_ELASTIC_ALPHA = 120
    AUG_ELASTIC_SIGMA = 6
    AUG_ELASTIC_P = 0.2

    # Geometric settings
    AUG_SHIFT_SCALE_ROTATE_P = 0.5
    AUG_HORIZONTAL_FLIP_P = 0.5

    # =========================================================================
    # Utility Methods
    # =========================================================================
    @classmethod
    def setup(cls):
        """
        Ensures necessary working directories exist.
        """
        os.makedirs(cls.WORKING_DIR, exist_ok=True)
        os.makedirs(cls.SUBMISSION_DIR, exist_ok=True)

    @staticmethod
    def set_seed(seed=42):
        """
        Sets global random seeds for reproducibility.
        """
        random.seed(seed)
        os.environ["PYTHONHASHSEED"] = str(seed)
        np.random.seed(seed)
        torch.manual_seed(seed)
        torch.cuda.manual_seed(seed)
        torch.backends.cudnn.deterministic = True
        torch.backends.cudnn.benchmark = False
